db-ivf-search.solution:
def ivf_search(centroids, vectors, query, nprobe, k):
    def d2(a, b):
        return sum((x - y) * (x - y) for x, y in zip(a, b))

    lists = [[] for _ in centroids]
    for i, v in enumerate(vectors):
        best = min(range(len(centroids)), key=lambda c: (d2(v, centroids[c]), c))
        lists[best].append(i)
    probe = sorted(range(len(centroids)), key=lambda c: (d2(query, centroids[c]), c))[:nprobe]
    cand = [i for c in probe for i in lists[c]]
    cand.sort(key=lambda i: (d2(query, vectors[i]), i))
    return cand[:k]

db-graph-traverse.solution:
def reachable(triples, start, predicate):
    out_edges = {}
    for s, p, o in triples:
        if p == predicate:
            out_edges.setdefault(s, []).append(o)
    seen = set()
    todo = list(out_edges.get(start, []))
    while todo:
        v = todo.pop()
        if v in seen:
            continue
        seen.add(v)
        todo.extend(out_edges.get(v, []))
    return sorted(seen)

db-wal-replay.solution:
def replay(log):
    state = {}
    pending = {}                       # tx -> list of buffered operations
    for rec in log:
        kind, tx = rec[0], rec[1]
        if kind == "begin":
            pending[tx] = []
        elif kind == "set":
            pending.setdefault(tx, []).append((rec[2], rec[3], False))
        elif kind == "delete":
            pending.setdefault(tx, []).append((rec[2], None, True))
        elif kind == "commit":
            for key, value, is_delete in pending.pop(tx, []):
                if is_delete:
                    state.pop(key, None)
                else:
                    state[key] = value
        elif kind == "abort":
            pending.pop(tx, None)
    return [[k, state[k]] for k in sorted(state)]

db-bitmap-rle.solution:
def bitmap_rle(column, value):
    if not column:
        return []
    runs = []
    current_bit, count = 0, 0
    for x in column:
        bit = 1 if x == value else 0
        if bit == current_bit:
            count += 1
        else:
            runs.append(count)
            current_bit, count = bit, 1
    runs.append(count)
    return runs

